package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Real;
    in attribute io_1 : Boolean;
    in attribute io_2 : Integer;
    attribute lastValidDistanceCm : Real := 400.0;
    attribute distanceValidHeld : Boolean := false;
    perform action tick {
      first start;
      then if io_1 {
        first start;
        then assign lastValidDistanceCm := io_0;
        then assign distanceValidHeld := true;
      } else {
        first start;
        then assign distanceValidHeld := false;
      }
    }
    out attribute serial_0_trigger : Boolean = true;
    out attribute serial_0_value_0 : Real = (if distanceValidHeld ? lastValidDistanceCm else lastValidDistanceCm);
  }
  part system : Controller;
}
